private int parseEndOfLine(String headerPart,int end){
    // Check if the current position is already at the end of the string
    if (end >= headerPart.length() - 1) {
        return end;
    }
    // Check if the next character is a newline character
    if (headerPart.charAt(end + 1) == '\r' && headerPart.charAt(end + 2) == '\n') {
        return end + 2;
    }
    // If the next character is not a newline, continue searching
    for (int i = end + 1; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    // If the end of the string is reached without finding a newline, return the current position
    return end;
}

private int parseEndOfLine(String headerPart, int end) {
    int index = end;
    while (index < headerPart.length()) {
        if (headerPart.charAt(index) == '\r') {
            break;
        }
        index++;
    }
    return index;
}

