    List<TimeRange> timeRanges = new ArrayList<>();
    long splitStart = start;
    long splitEnd = splitStart + FETCH_DATA_DURATION;
    while (splitEnd < end) {
        timeRanges.add(new TimeRange(splitStart, splitEnd));
        splitStart = splitEnd;
