    // Initialize local variables
    int strLen = str.length();
    int i = 0;
    int utf8ByteCount = 0;
    byte[] utf8Bytes = new byte[strLen * 4];

    // Loop through all characters in the string
    while (i < strLen) {
        // Get the current character and its UTF-16 code unit
        char c = str.charAt(i);
        int codeUnit = (int) c;

        // Check for surrogate pairs
        if (Character.isHighSurrogate(c)) {
            // Increment i and get the low surrogate code unit
            i++;
            int lowSurrogate = (int) str.charAt(i);

            // Combine the surrogate pairs to get the Unicode code point
            int codePoint = Character.toCodePoint(codeUnit, lowSurrogate);

            // Encode the Unicode code point as a UTF-8 byte sequence
            int utf8ByteCount = 1;
            int utf8Bytes[4] = {
                (byte) (codePoint >>> 24),
                (byte) (codePoint >>> 16),
                (byte) (codePoint >>> 8),
                (byte) codePoint
            };
        } else {
            // Encode the UTF-16 code unit as a UTF-8 byte sequence
            int utf8ByteCount = 1;
            int utf8Bytes[4] = {(byte) codeUnit};
        }

        // Write the UTF-8 byte sequence to the LinkedBuffer
        for (int j = 0; j < utf8ByteCount; j++) {
            lb.writeByte(utf8Bytes[j]);
        }

        // Increment i to move to the next character
        i++;
    }

    // Return the updated LinkedBuffer
    return lb;
