private List<ExtendedType> extractArgumentTypes(final String descriptor) {
    List<ExtendedType> argTypes = new ArrayList<>();
    int numParams = countParameters(descriptor);
    int currentPos = descriptor.indexOf("(");
    while (numParams > 0 && currentPos != -1) {
        int nextPos = descriptor.indexOf(";", currentPos + 1);
        String argType = descriptor.substring(currentPos + 1, nextPos);
        if (argType.equals("D")) {
            argTypes.add(new ExtendedType(Category.Prim, 2));
        } else if (argType.equals("J")) {
            argTypes.add(new ExtendedType(Category.Prim, 2));
        } else if (isObjectType(argType)) {
            argTypes.add(new ExtendedType(Category.Obj, 2));
        } else {
            break;
        }
        numParams--;
        currentPos = nextPos;
    }
    return argTypes;
}

/**
* Counts the total number of parameters in a method descriptor.
*/
private int countParameters(final String descriptor) {
    int numParams = 0;
    int currentPos = descriptor.indexOf("(");
    while (currentPos != -1) {
        int nextPos = descriptor.indexOf(";", currentPos + 1);
        if (nextPos == -1) {
            break;
        }
        String paramType = descriptor.substring(currentPos + 1, nextPos);
        if (isObjectType(paramType)) {
            numParams++;
        }
        currentPos = nextPos;
    }
    return numParams;
}

