public static String encodeTemplateNames(String s) {
    if (s == null) {
        return s;
    }
    StringBuffer encodedString = new StringBuffer();
    int cursor = 0;
    int lastOpenBrace = -1;
    while (cursor < s.length()) {
        char current = s.charAt(cursor);
        if (current == '{') {
            lastOpenBrace = cursor;
        } else if (current == '}') {
            if (lastOpenBrace != -1 && lastOpenBrace + 1 < cursor) {
                String templateParam = s.substring(lastOpenBrace + 1, cursor);
                try {
                    encodedString.append(URLEncoder.encode(templateParam, "UTF-8"));
                } catch (UnsupportedEncodingException e) {
                    throw new RuntimeException(e);
                }
            }
            lastOpenBrace = -1;
        } else {
            encodedString.append(current);
        }
        cursor++;
    }
    if (lastOpenBrace != -1) {
        encodedString.append('}');
    }
    return encodedString.toString();
}

