public static String applyRelativePath(String path, String relativePath) {
    // Split the relative path into its components
    String[] relativeComponents = relativePath.split("/");
    // Split the path into its components
    String[] pathComponents = path.split("/");
    // Iterate through the relative components, applying them to the path
    for (String component : relativeComponents) {
        if (component.equals(".")) {
            // Do nothing
        } else if (component.equals("..")) {
            // Remove the last component from the path
            if (!pathComponents.isEmpty()) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else {
            // Add the component to the path
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = component;
        }
    }
    // Join the path components back together
    return String.join("/", pathComponents);
}

