/**
 * Returns the index of the last extension separator character, which is a dot.
 * <p>This method also checks that there is no directory separator after the last dot. To do this it uses {@link #indexOfLastSeparator(String)} which will handle a file in either Unix or Windows format.
 * <p>The output will be the same irrespective of the machine that the code is running on.
 * @param filename the filename to find the last path separator in, null returns -1
 * @return the index of the last separator character, or -1 if there is no such character
 */
public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int index = indexOfLastSeparator(filename);
    int extIndex = filename.lastIndexOf(".", index);
    if (extIndex == -1 || extIndex == 0) {
        return -1;
    }
    String ext = filename.substring(extIndex + 1);
    if (ext.isEmpty()) {
        return -1;
    }
    return extIndex;
}

