    int index = filename.lastIndexOf('.', lastSeparatorIndex);
    if (index >= lastSeparatorIndex) {
        // There is a dot after the last separator, so it is the extension separator
        return index;
    } else {
        // There is no dot after the last separator, so there is no extension separator
        return -1;
    }
}

