    if (str == null || substring == null) {
        return false;
    }
    int strLength = str.length();
    int substrLength = substring.length();
    if (index < 0 || index > strLength - substrLength) {
        return false;
    }
    for (int i = 0; i < substrLength; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

