        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            ProfileAnalyzeTimeRange currentRange = null;
            while ((line = reader.readLine()) != null) {
                if (line.isEmpty()) {
                    continue;
                }
                if (currentRange == null) {
                    long timestamp = Long.parseLong(line.trim());
                    currentRange = new ProfileAnalyzeTimeRange(timestamp, Long.MAX_VALUE);
                } else if (currentRange.contains(timestamp)) {
                    String[] parts = line.split(" ");
                    String threadName = parts[0];
                    boolean isDaemon = parts[1].equals("daemon");
                    long threadId = Long.parseLong(parts[2]);
                    int priority = Integer.parseInt(parts[3]);
                    int groupId = Integer.parseInt(parts[4]);
                    threadSnapshots.add(new ThreadSnapshot(threadName, isDaemon, threadId, priority, groupId));
                } else {
                    currentRange = null;
                }
            }
        }
